const dailyTrendData = useMemo(() => {
   const dataMap = new Map();
   const sd = new Date(selectedDate);
   const sdYear = sd.getFullYear();
   const sdMonth = sd.getMonth();

   const daysInMonth = new Date(sdYear, sdMonth + 1, 0).getDate();
   for (let i = 1; i <= daysInMonth; i++) {
       const dateStr = `${sdYear}-${String(sdMonth + 1).padStart(2, '0')}-${String(i).padStart(2, '0')}`;
       const dataObj: any = { date: dateStr, day: i, total: 0 };
       PRODUCTS_LIST.forEach(p => dataObj[p] = 0);
       dataMap.set(dateStr, dataObj);
   }

   validEntries.forEach(entry => {
       if (entry.recordType && entry.recordType !== 'achievement') return;
       if (selectedBusinessBranch !== 'all' && entry.branchId !== selectedBusinessBranch) return;

       const ed = new Date(entry.entryDate);
       if (ed.getFullYear() === sdYear && ed.getMonth() === sdMonth) {
           const dayData = dataMap.get(entry.entryDate);
           if (dayData) {
               entry.items.forEach(item => {
                   const cat = item.category || 'Loan';
                   const prod = item.product || 'Personal Loan';
                   let achAmt = 0;
                   if (cat === 'Loan') achAmt = Number(item.disbursedAmount) || 0;
                   else if (cat === 'Insurance') achAmt = item.fileStatus === 'Issued' ? (Number(item.amount) || 0) : 0;
                   else achAmt = Number(item.amount) || 0;

                   if (dayData[prod] !== undefined) {
                       dayData[prod] += achAmt;
                   }
                   dayData.total += achAmt;
               });
           }
       }
   });

   let runningTotal = 0;
   const runningProds: Record<string, number> = {};
   PRODUCTS_LIST.forEach(p => runningProds[p] = 0);

   return Array.from(dataMap.values()).map(dayData => {
       runningTotal += dayData.total;
       PRODUCTS_LIST.forEach(p => {
           runningProds[p] += dayData[p];
           dayData[`${p}_cum`] = runningProds[p];
       });
       dayData.total_cum = runningTotal;
       return dayData;
   });
}, [validEntries, selectedDate, selectedBusinessBranch]);

